ALTER TABLE "technical_results" ADD CONSTRAINT "technical_results_auxiliary_units" CHECK (("technical_results"."uncertainty_unit_code" IS NULL OR "technical_results"."uncertainty_unit_code" ~ '^[A-Za-z0-9][A-Za-z0-9./*^%_-]{0,39}$') AND ("technical_results"."tolerance_unit_code" IS NULL OR "technical_results"."tolerance_unit_code" ~ '^[A-Za-z0-9][A-Za-z0-9./*^%_-]{0,39}$') AND ("technical_results"."uncertainty_coverage" IS NULL OR char_length(btrim("technical_results"."uncertainty_coverage")) > 0) AND ("technical_results"."tolerance_rule" IS NULL OR char_length(btrim("technical_results"."tolerance_rule")) > 0));--> statement-breakpoint
ALTER TABLE "technical_results" ADD CONSTRAINT "technical_results_tolerance_order" CHECK ("technical_results"."tolerance_lower_text" IS NULL OR "technical_results"."tolerance_upper_text" IS NULL OR "technical_results"."tolerance_lower_text"::numeric <= "technical_results"."tolerance_upper_text"::numeric);--> statement-breakpoint
ALTER TABLE "technical_results" ADD CONSTRAINT "technical_results_text_not_blank" CHECK ("technical_results"."text_value" IS NULL OR char_length(btrim("technical_results"."text_value")) > 0);